/* sound.js: every sound effect, generated by the browser (Web Audio). There are no audio files.
 *
 * Two building blocks make all the sounds:
 *   tone()   a pitch that slides from one frequency to another (gulps, plops, gurgles)
 *   noise()  a burst of filtered hiss (crunches, squelches, splashes)
 *
 * Browsers only allow sound after the user has clicked something, so nothing plays until then.
 * To use a recording instead, replace the matching entry in FX with code that plays your file.
 */
(function (root) {
  'use strict';
  let ctx = null, master = null, enabled = true, noiseBuf = null;
  const rnd = (a, b) => a + Math.random() * (b - a);

  function audio() {
    if (!enabled) return null;
    try {
      if (!ctx) {
        const AC = root.AudioContext || root.webkitAudioContext;
        if (!AC) return null;
        ctx = new AC();
        master = ctx.createGain(); master.gain.value = 0.6; master.connect(ctx.destination);
        noiseBuf = ctx.createBuffer(1, ctx.sampleRate, ctx.sampleRate);
        const d = noiseBuf.getChannelData(0);
        for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
      }
      if (ctx.state === 'suspended') ctx.resume();
      return ctx;
    } catch (e) { return null; }
  }
  function envelope(g, t, dur, peak) {
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(peak, t + Math.min(0.015, dur / 4));
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  }
  function tone(f0, f1, dur, o) {
    const a = audio(); if (!a) return;
    o = o || {};
    const t = a.currentTime + (o.at || 0), osc = a.createOscillator(), g = a.createGain();
    osc.type = o.type || 'sine';
    osc.frequency.setValueAtTime(f0, t);
    osc.frequency.exponentialRampToValueAtTime(Math.max(20, f1), t + dur);
    envelope(g, t, dur, o.gain || 0.3);
    osc.connect(g); g.connect(master); osc.start(t); osc.stop(t + dur + 0.02);
  }
  function noise(dur, o) {
    const a = audio(); if (!a) return;
    o = o || {};
    const t = a.currentTime + (o.at || 0), src = a.createBufferSource(), f = a.createBiquadFilter(), g = a.createGain();
    src.buffer = noiseBuf; src.loop = true;
    f.type = o.filter || 'bandpass'; f.Q.value = o.q || 1;
    f.frequency.setValueAtTime(o.freq || 1500, t);
    if (o.freqTo) f.frequency.exponentialRampToValueAtTime(o.freqTo, t + dur);
    envelope(g, t, dur, o.gain || 0.3);
    src.connect(f); f.connect(g); g.connect(master); src.start(t, rnd(0, 0.5)); src.stop(t + dur + 0.02);
  }

  const FX = {
    click() { tone(700, 500, 0.05, { type: 'triangle', gain: 0.2 }); },
    lift() { tone(420, 620, 0.05, { type: 'triangle', gain: 0.12 }); },
    buzz() { tone(150, 110, 0.18, { type: 'sawtooth', gain: 0.15 }); },
    chew() {                                             // a crunch, then the jaws closing
      noise(0.07, { freq: rnd(1500, 2600), q: 0.8, gain: 0.5 });
      noise(0.05, { freq: rnd(2500, 4000), q: 1.5, gain: 0.25, at: 0.03 });
      tone(170, 90, 0.07, { gain: 0.25, at: 0.01 });
    },
    gulp() { tone(300, 110, 0.13, { gain: 0.4 }); tone(120, 360, 0.11, { gain: 0.35, at: 0.14 }); },
    squeeze() { tone(180, 120, 0.12, { gain: 0.12 }); noise(0.12, { filter: 'lowpass', freq: 500, gain: 0.08 }); },
    gurgle() {                                           // a few rising bubbles
      const n = 3 + Math.floor(rnd(0, 3)); let at = 0;
      for (let i = 0; i < n; i++) { const f = rnd(70, 170); tone(f, f * rnd(1.5, 2.2), 0.09, { gain: 0.3, at }); at += rnd(0.06, 0.13); }
      noise(0.3, { filter: 'lowpass', freq: 300, gain: 0.12 });
    },
    squelch() { noise(0.16, { filter: 'lowpass', freq: 900, freqTo: 250, gain: 0.16 }); tone(rnd(200, 320), rnd(110, 150), 0.1, { gain: 0.1, at: 0.04 }); },
    absorb() { tone(rnd(900, 1300), 1700, 0.05, { gain: 0.035 }); },
    rumble() { tone(rnd(55, 75), 42, 0.35, { type: 'triangle', gain: 0.3 }); noise(0.3, { filter: 'lowpass', freq: 160, gain: 0.15 }); },
    plop() { tone(520, 85, 0.2, { gain: 0.5 }); noise(0.08, { filter: 'lowpass', freq: 700, gain: 0.15, at: 0.16 }); },
    splat() {                                            // a wet, rattling burst
      for (let i = 0; i < 9; i++) tone(rnd(70, 120), rnd(50, 90), 0.07, { type: 'sawtooth', gain: 0.22, at: i * 0.06 + rnd(0, 0.02) });
      noise(0.7, { filter: 'lowpass', freq: 1400, freqTo: 300, gain: 0.3 });
      for (let i = 0; i < 6; i++) noise(0.05, { freq: rnd(900, 2200), gain: 0.2, at: 0.1 + i * 0.09 });
    },
    spill() { noise(0.5, { filter: 'lowpass', freq: 1800, freqTo: 250, gain: 0.35 }); tone(260, 70, 0.3, { gain: 0.25, at: 0.05 }); },
    win() { [523, 659, 784, 1047].forEach((f, i) => tone(f, f, 0.16, { type: 'triangle', gain: 0.22, at: i * 0.11 })); },
    meh() { tone(440, 440, 0.15, { type: 'triangle', gain: 0.2 }); tone(392, 392, 0.25, { type: 'triangle', gain: 0.2, at: 0.17 }); },
    lose() { [392, 370, 349].forEach((f, i) => tone(f, f * 0.97, 0.25, { type: 'sawtooth', gain: 0.12, at: i * 0.27 })); tone(330, 250, 0.7, { type: 'sawtooth', gain: 0.12, at: 0.81 }); }
  };

  root.DigestSound = {
    play(name) { if (enabled && FX[name]) { try { FX[name](); } catch (e) { /* sound is optional */ } } },
    setEnabled(v) { enabled = !!v; if (!enabled && ctx && ctx.state === 'running') ctx.suspend(); },
    get enabled() { return enabled; },
    names: Object.keys(FX)
  };
})(typeof self !== 'undefined' ? self : this);
